#include <stdio.h>

int main(void)
{
    int n, m, i, j;
    int a[105][105];

    scanf("%d%d", &n, &m);
    for (i = 0; i < n; i++)
        for (j = 0; j < m; j++)
            scanf("%d", &a[i][j]);

    /* 转置输出：新矩阵 m 行 n 列 */
