}

#include <stdio.h>

int main(void)
{
    int n, k, s, p;
    double amount;
    double sale[5][4] = {0};   /* 行：产品 1-5；列：销售员 1-4 */
    double rowTotal, colTotal, grand = 0;

    scanf("%d", &n);
    for (k = 0; k < n; k++) {
        scanf("%d%d%lf", &s, &p, &amount);
        sale[p - 1][s - 1] += amount;
    }

    for (p = 0; p < 5; p++) {
        rowTotal = 0;
        for (s = 0; s < 4; s++)
            rowTotal += sale[p][s];
        for (s = 0; s < 4; s++)
            printf("%.1f\t", sale[p][s]);
        printf("%.1f\n", rowTotal);
        grand += rowTotal;
    }

    for (s = 0; s < 4; s++) {
        colTotal = 0;
        for (p = 0; p < 5; p++)
            colTotal += sale[p][s];
        printf("%.1f\t", colTotal);
    }
    printf("%.1f\n", grand);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int m, n, i, j, x, y, sum = 0;
    int a[15][15];

    scanf("%d%d", &m, &n);
    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++)
            scanf("%d", &a[i][j]);
    scanf("%d%d", &x, &y);

    for (i = x - 2; i <= x; i++)         /* 行下标：x-2、x-1、x */
        for (j = y - 2; j <= y; j++) {   /* 列下标：y-2、y-1、y */
            if (i < 0 || i >= m || j < 0 || j >= n)
                continue;                /* 越界跳过 */
            if (i == x - 1 && j == y - 1)
                continue;                /* 跳过中心点自身 */
            sum += a[i][j];
        }
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n, m, i, j;
    int a[105][105];

    scanf("%d%d", &n, &m);
    for (i = 0; i < n; i++)
        for (j = 0; j < m; j++)
            scanf("%d", &a[i][j]);

    for (i = 0; i < n; i++) {
        int maxCol = 0;
        int isSaddle = 1;
        for (j = 1; j < m; j++)
            if (a[i][j] > a[i][maxCol])
                maxCol = j;
        for (j = 0; j < n; j++)
            if (a[j][maxCol] < a[i][maxCol]) {
                isSaddle = 0;
                break;
            }
        if (isSaddle) {
            printf("The saddle point is (%d,%d)=%d.\n",
                   i, maxCol, a[i][maxCol]);
            return 0;
        }
    }
    printf("There is no saddle point in the matrix.\n");
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n, i, j, k;
    int a[105][105];
    long long sum[105];

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        sum[i] = 0;
        for (j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
            sum[i] += a[i][j];
        }
    }

    /* 各行元素个数同为 n，比较平均值等价于比较行和；插入排序保证稳定 */
    for (i = 1; i < n; i++) {
        long long keySum = sum[i];
        int keyRow[105];
        for (j = 0; j < n; j++)
            keyRow[j] = a[i][j];
        k = i - 1;
        while (k >= 0 && sum[k] > keySum) {   /* 严格大于才后移，相等保持原序 */
            sum[k + 1] = sum[k];
            for (j = 0; j < n; j++)
                a[k + 1][j] = a[k][j];
            k--;
        }
        sum[k + 1] = keySum;
        for (j = 0; j < n; j++)
            a[k + 1][j] = keyRow[j];
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++)
            printf(j ? " %d" : "%d", a[i][j]);
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n, s, r, c, value = 1;
    int a[105][105];

    scanf("%d", &n);
    for (s = 0; s <= 2 * n - 2; s++) {
        if (s % 2 == 0) {          /* 偶斜线：从右上往左下填 */
            c = s < n ? s : n - 1;
            r = s - c;
            while (r < n && c >= 0) {
                a[r][c] = value++;
                r++;
                c--;
            }
        } else {                   /* 奇斜线：从左下往右上填 */
            r = s < n ? s : n - 1;
            c = s - r;
            while (r >= 0 && c < n) {
                a[r][c] = value++;
                r--;
                c++;
            }
        }
    }

    for (r = 0; r < n; r++) {
        for (c = 0; c < n; c++)
            printf(c ? " %d" : "%d", a[r][c]);
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n, i, j;
    int a[105][105];
    long long boundary = 0, diagonal = 0;

    scanf("%d", &n);
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            scanf("%d", &a[i][j]);

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++) {
            if (i == 0 || i == n - 1 || j == 0 || j == n - 1)
                boundary += a[i][j];
            if (i == j || i + j == n - 1)
                diagonal += a[i][j];   /* 交点只加一次 */
        }

    printf("%lld\n%lld\n", boundary, diagonal);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n, i, j;
    int a[105][105];

    scanf("%d", &n);
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            scanf("%d", &a[i][j]);

    /* 顺时针旋转 90°：新矩阵 [i][j] = 原矩阵 [n-1-j][i] */
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++)
            printf(j ? " %d" : "%d", a[n - 1 - j][i]);
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int m, n, i, j, x;
    int nonzero[105] = {0};    /* 每行非零元素个数 */
    int zeros[105] = {0};      /* 每行零元素个数 */
    int count = 0;             /* 非零元素总数 */
    int bestRow = 0, bestZeros = -1;
    long long sum = 0;

    scanf("%d%d", &m, &n);
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) {
            scanf("%d", &x);
            if (x != 0) {
                count++;
                sum += x;
                nonzero[i]++;
            } else {
                zeros[i]++;
            }
        }
    }

    for (i = 0; i < m; i++) {
        if (zeros[i] > bestZeros) {
            bestZeros = zeros[i];
            bestRow = i + 1;
        }
    }
    if (bestZeros == 0)            /* 整个矩阵没有 0 */
        bestRow = 0;

    printf("%d %lld\n", count, sum);
    printf("%d\n", bestRow);
    for (i = 0; i < m; i++)
        printf(i ? " %d" : "%d", nonzero[i]);
    printf("\n");
    return 0;
}
